styles:
.reader-quote {
  font-style: italic;
  color: var(--reader-accent-start, #d4a574);
  font-weight: 500;
}
.reader-ellipsis {
  letter-spacing: 6px;
  opacity: 0.6;
}
.reader-dash {
  letter-spacing: 4px;
  opacity: 0.7;
}
.reader-speak {
  color: var(--reader-strong, #e8c99b);
  font-weight: 700;
  font-size: 1.05em;
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3.2em;
  line-height: 0.75;
  padding-right: 8px;
  padding-top: 6px;
  color: var(--reader-accent-start, #d4a574);
  font-weight: 900;
  font-family: 'STKaiti', 'KaiTi', serif;
}
